// HMAC-Signatur pruefen: App/Worker signieren event\ntimestamp\nnonce\nbody.
import crypto from 'crypto';
const secret = $env.N8N_HMAC_SECRET;
const headers = $input.item.json.headers || {};
const body = typeof $input.item.json.body === 'string'
  ? $input.item.json.body
  : JSON.stringify($input.item.json.body ?? {});
const sig = headers['x-taxtronik-signature'] || headers['X-Taxtronik-Signature'] || '';
const ts = headers['x-taxtronik-timestamp'] || headers['X-Taxtronik-Timestamp'] || '';
const event = headers['x-taxtronik-event'] || headers['X-Taxtronik-Event'] || '';
const nonce = headers['x-taxtronik-nonce'] || headers['X-Taxtronik-Nonce'] || '';
if (!sig || !ts || !event || !nonce) {
  throw new Error('HMAC-Header fehlen');
}
const tsNumber = Number(ts);
if (!Number.isFinite(tsNumber) || Math.abs(Date.now() - tsNumber) > 5 * 60 * 1000) {
  throw new Error('HMAC-Timestamp ungueltig');
}
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(`${event}\n${ts}\n${nonce}\n${body}`).digest('hex');
if (sig !== expected) {
  throw new Error('HMAC-Signatur ungueltig');
}
return $input.item;

// >>> HIER die eigentliche Recherche einsetzen (LLM / Websuche / interne KB). <<<
// Eingang: $json.body.payload = { researchRequestId, rechtsfrage, normAnker,
//   governanceTyp, anonymizedText, katalogVersion }. Der Payload ist BEREITS
// anonymisiert (Mandantendaten durch Platzhalter ersetzt) — keine Klartextdaten.
// Ausgang muss { researchRequestId, title, body, source } liefern; researchRequestId
// MUSS unveraendert zurueck (Korrelations-Token fuer die automatische Zuordnung).
const p = ($json.body && $json.body.payload) || {};
const titel = ('Recherche: ' + (p.rechtsfrage || '')).slice(0, 200);
const ergebnis = 'TODO: Recherche-Ergebnis hier erzeugen. Rechtsfrage: ' + (p.rechtsfrage || '') + ' | Normanker: ' + ((p.normAnker || []).join(', ')) + ' | Governance: ' + (p.governanceTyp || '-');
return { json: { researchRequestId: p.researchRequestId, title: titel, body: ergebnis, source: 'n8n' } };

// Inbound-Signatur fuer den Rueckruf an /api/n8n/research-result.
// Format (siehe verify.ts): sha256=hex(hmac("POST <path>" + "\n" + ts + "\n" + body)).
// Die Signatur dient gleichzeitig als Replay-Nonce — pro Aufruf neu.
import crypto from 'crypto';
const secret = $env.N8N_HMAC_SECRET;
const result = { researchRequestId: $json.researchRequestId, title: $json.title, body: $json.body, source: $json.source || 'n8n' };
const bodyStr = JSON.stringify(result);
const ts = String(Date.now());
const payload = 'POST /api/n8n/research-result' + '\n' + ts + '\n' + bodyStr;
const sig = 'sha256=' + crypto.createHmac('sha256', secret).update(payload).digest('hex');
return { json: { bodyStr, ts, sig } };
